def transform(grid):
    # Find the compact framed rectangle with a solid 3-colored interior; encode
    # that interior as the output mask.
    h,w=len(grid),len(grid[0])
    for r in range(h-2):
        for c in range(w-2):
            if grid[r][c] != 1: continue
            for r1 in range(r+2,h):
                for c1 in range(c+2,w):
                    if all(grid[r][x]==1 and grid[r1][x]==1 for x in range(c,c1+1)) and all(grid[y][c]==1 and grid[y][c1]==1 for y in range(r,r1+1)):
                        inner=[grid[y][c+1:c1] for y in range(r+1,r1)]
                        if inner and all(v==3 for row in inner for v in row):
                            return [[8 if v==3 else 0 for v in inner[0]]]
    return [[0]]
